import axios from "axios";

const TMDB_API_KEY = "YOUR_TMb56be59cfcfc26fbad50e51fb6341736DB_API_KEY"; // 실제 키로 대체
const BASE_URL = "https://api.themoviedb.org/3"; // ✅ 이 줄이 필요합니다!

export const getPosterFromTMDB = async (movieTitle, openDate) => {
  try {
    const response = await axios.get(`${BASE_URL}/search/movie`, {
      params: {
        api_key: TMDB_API_KEY,
        query: movieTitle,
        language: "ko-KR",
      },
    });

    const results = response.data.results;
    if (results.length === 0) return null;

    let matched = results.find((m) => m.release_date === openDate);
    if (!matched && openDate) {
      matched = results.find((m) =>
        m.release_date?.startsWith(openDate.slice(0, 4))
      );
    }

    const target = matched || results[0];

    if (
      openDate &&
      target?.release_date &&
      Math.abs(new Date(openDate) - new Date(target.release_date)) >
        1000 * 60 * 60 * 24 * 365
    ) {
      return null;
    }

    return target.poster_path
      ? `https://image.tmdb.org/t/p/w500${target.poster_path}`
      : null;
  } catch (error) {
    console.error("TMDB 포스터 가져오기 실패:", error);
    return null;
  }
};
